def test_stack_preserve_dtype(self) -> None:
    # regression test for GH7259 - stack should not change coord dtype
    da = DataArray(
        [0, 1], dims=("a",), coords={"a": np.array([0, 1], dtype="i4")}
    )
    assert da["a"].values.dtype == da.stack(b=("a",))["a"].values.dtype

    # 2d case
    da2 = DataArray(
        [[0, 1], [2, 3]],
        dims=("x", "y"),
        coords={
            "x": np.array([0, 1], dtype="i4"),
            "y": np.array([2, 3], dtype="i4"),
        },
    )
    stacked = da2.stack(z=("x", "y"))
    assert stacked["x"].values.dtype == np.dtype("i4")
    assert stacked["y"].values.dtype == np.dtype("i4")

